<script type="application/ld+json">
{"@context": "https://schema.org", "@type": "FAQPage", "mainEntity": [{"@type": "Question", "name": "Что такое АСТ ГОЗ?", "acceptedAnswer": {"@type": "Answer", "text": "Это специализированная электронная площадка для проведения закрытых конкурентных закупок в электронной форме, в том числе по гособоронзаказу и закупкам со сведениями гостайны. Включена в перечень операторов специализированных площадок распоряжением Правительства РФ от 12.07.2018 № 1447-р."}}, {"@type": "Question", "name": "Кто оператор АСТ ГОЗ?", "acceptedAnswer": {"@type": "Answer", "text": "Оператор — ООО «Автоматизированная система торгов государственного оборонного заказа» (ООО «АСТ ГОЗ»). Организационно-правовая форма — общество с ограниченной ответственностью, а не акционерное общество."}}, {"@type": "Question", "name": "На каком основании работает площадка?", "acceptedAnswer": {"@type": "Answer", "text": "На основании распоряжения Правительства РФ от 12.07.2018 № 1447-р (в редакции от 23.11.2022), которым утверждены перечни операторов электронных и специализированных электронных площадок."}}, {"@type": "Question", "name": "Чем АСТ ГОЗ отличается от обычных площадок?", "acceptedAnswer": {"@type": "Answer", "text": "Обычные восемь федеральных площадок проводят открытые процедуры через интернет. АСТ ГОЗ ведёт закрытые процедуры в защищённом контуре, сведения о которых не публикуются открыто, а участие требует допуска к гостайне и аттестованного рабочего места."}}, {"@type": "Question", "name": "АСТ ГОЗ — единственная площадка для ГОЗ?", "acceptedAnswer": {"@type": "Answer", "text": "Нет. С конца 2022 года перечень специализированных площадок расширен, и их несколько. Утверждение об единственной площадке устарело."}}, {"@type": "Question", "name": "Что нужно для работы на площадке?", "acceptedAnswer": {"@type": "Answer", "text": "Как правило: усиленная квалифицированная электронная подпись, сертифицированные СКЗИ, аттестованное защищённое рабочее место, при работе с гостайной — лицензия ФСБ, а также аккредитация на площадке. Точные требования задаёт оператор."}}, {"@type": "Question", "name": "Как связаны АСТ ГОЗ и казначейское сопровождение?", "acceptedAnswer": {"@type": "Answer", "text": "Площадка закрывает этап заключения контракта. Его дальнейшее исполнение и расчёты подпадают под казначейское или банковское сопровождение ГОЗ: присваивается ИГК, открывается отдельный счёт, ведётся раздельный учёт."}}, {"@type": "Question", "name": "Где найти точный регламент регистрации?", "acceptedAnswer": {"@type": "Answer", "text": "Регламент доступа и аккредитации устанавливает оператор площадки. Поскольку часть процедур идёт в защищённом контуре, актуальные инструкции и требования уточняют непосредственно у оператора и в своём удостоверяющем центре."}}, {"@type": "Question", "name": "Какой официальный сайт у АСТ ГОЗ?", "acceptedAnswer": {"@type": "Answer", "text": "Официальный сайт площадки — astgoz.ru. Вход в личный кабинет и подача заявления на аккредитацию выполняются через него по квалифицированной электронной подписи."}}, {"@type": "Question", "name": "Как войти в личный кабинет АСТ ГОЗ?", "acceptedAnswer": {"@type": "Answer", "text": "Вход выполняется с официального сайта astgoz.ru по сертификату квалифицированной электронной подписи уполномоченного лица. Для входа должны быть настроены криптопровайдер, браузерный плагин и корневые сертификаты удостоверяющего центра."}}, {"@type": "Question", "name": "Сколько действует аккредитация на специализированной электронной площадке?", "acceptedAnswer": {"@type": "Answer", "text": "Три года со дня направления оператором уведомления о принятии решения об аккредитации (пункт 17 Положения, утверждённого постановлением Правительства РФ № 223). Пройти аккредитацию на новый срок можно не ранее чем за шесть месяцев до окончания действующей."}}, {"@type": "Question", "name": "Почему нельзя подать заявку при действующей аккредитации?", "acceptedAnswer": {"@type": "Answer", "text": "Скорее всего сработало ограничение пункта 17 Положения: участник не вправе подать заявку на участие в закрытых электронных процедурах за три месяца до даты окончания срока своей аккредитации. Нужно проходить аккредитацию на новый срок."}}, {"@type": "Question", "name": "Что нужно для участия в закупках со сведениями государственной тайны?", "acceptedAnswer": {"@type": "Answer", "text": "Помимо аккредитации на площадке — лицензия на проведение работ с использованием сведений, составляющих государственную тайну, с указанием соответствующей степени секретности, и подключение к сети шифрованной связи площадки. Доступ открывается после такого подключения."}}, {"@type": "Question", "name": "Сколько времени занимает аккредитация?", "acceptedAnswer": {"@type": "Answer", "text": "Решение об аккредитации или об отказе оператор принимает и направляет уведомление в течение одного рабочего дня со дня поступления заявления. Дольше обычно занимает подготовка: регистрация в единой информационной системе, выпуск подписи и настройка защищённого канала."}}, {"@type": "Question", "name": "Почему отказали в аккредитации?", "acceptedAnswer": {"@type": "Answer", "text": "Единственное основание отказа по Положению — отсутствие регистрации участника закупки в единой информационной системе в электронной форме. Уведомление об отказе должно содержать указание на основание; после его устранения заявление подаётся повторно."}}]}
